    output.system.push(['Hi SEMANTIC ASSESSMENT GATE', `Semantic revision: ${m.semantic_assessment.revision}.`, 'The user message may be in any language. Do not classify it with language-specific keywords or translate it into an English keyword heuristic. Before any execution, call hi_intent_assess exactly once for this revision.', `Assessment phase: ${m.semantic_assessment.phase}.`, 'Submit assessment_json as a JSON object with: material:boolean; message_kind=mission|amendment|constraint|verification|stop|resume|non-material; task_kind=implementation|bug-fix|review|performance|release-readiness; scope=local|multi-file|repo-wide|external|multi-stream; risk=low|medium|high|authority-boundary; ambiguity=none|resolvable|contract-critical; dependency_class=independent|sequential|external-gated|unknown|independent-multi; required_capabilities:string[]; requested_external_actions:string[]; likely_verification:string[]; likely_targets:string[]; intent_signals:string[]; suppressed_intent_signals:string[].', 'Interpret semantic meaning directly in the user language. Use likely_targets only for explicit/high-confidence targets; deterministic technical targets are already preserved by Hi. Select intent_signals only for explicit methodology-relevant user intent; runtime evidence may activate additional methodologies later. requested_external_actions must contain only external effects the user actually requested; any non-empty value requires risk=authority-boundary.', `Allowed capabilities: ${SEMANTIC_CAPABILITIES.join(', ')}`, `Allowed requested external actions: ${SEMANTIC_EXTERNAL_ACTIONS.join(', ')}`, `Allowed verification kinds: ${SEMANTIC_VERIFICATION_KINDS.join(', ')}`, `Allowed intent signals: ${intentSignals.join(', ')}`, m.semantic_assessment.phase === 'initial' ? 'For initial assessment use message_kind=mission, or non-material with material=false.' : 'For follow-up assessment classify the user message as amendment, constraint, verification, stop, resume, or non-material. The other semantic fields describe the resulting mission state; preserve existing semantics unless the user actually changed them.', 'If the message is non-material/casual, set material=false; otherwise material=true. Still provide valid enum fields. Do not execute or delegate before the assessment is accepted.'].join('\n'));
